import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Event Handlers - October CMS - 3.x","titleTemplate":false,"description":"Design your API and update the page dynamically.","frontmatter":{"subtitle":"Design your API and update the page dynamically."},"headers":[{"level":2,"title":"AJAX Handlers","slug":"ajax-handlers","link":"#ajax-handlers","children":[{"level":3,"title":"Calling a Handler","slug":"calling-a-handler","link":"#calling-a-handler","children":[]},{"level":3,"title":"Form Serialization","slug":"form-serialization","link":"#form-serialization","children":[]},{"level":3,"title":"Generic Handler","slug":"generic-handler","link":"#generic-handler","children":[]},{"level":3,"title":"Component Handlers","slug":"component-handlers","link":"#component-handlers","children":[]}]},{"level":2,"title":"Redirects in AJAX Handlers","slug":"redirects-in-ajax-handlers","link":"#redirects-in-ajax-handlers","children":[]},{"level":2,"title":"Returning Data from AJAX Handlers","slug":"returning-data-from-ajax-handlers","link":"#returning-data-from-ajax-handlers","children":[]},{"level":2,"title":"Running Code Before Handlers","slug":"running-code-before-handlers","link":"#running-code-before-handlers","children":[]},{"level":2,"title":"Throwing an AJAX Exception","slug":"throwing-an-ajax-exception","link":"#throwing-an-ajax-exception","children":[]},{"level":2,"title":"Dispatching Browser Events","slug":"dispatching-browser-events","link":"#dispatching-browser-events","children":[]}],"relativePath":"3.x/cms/ajax/handlers.md","filePath":"3.x/cms/ajax/handlers.md"}'),u={name:"3.x/cms/ajax/handlers.md"};function r(d,n,k,h,g,m){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Event Handlers",-1)),s(e),n[1]||(n[1]=i(`<p>AJAX event handlers are API endpoints for the AJAX framework to communicate with the server. They can respond with raw data, redirect the browser or dynamically update partials on the page.</p><h2 id="ajax-handlers"><a href="#ajax-handlers" class="header-anchor">#</a> AJAX Handlers</h2><p>To create an AJAX handler, define it as a PHP function the page, partial or layout PHP section, or <a href="./../themes/components.html">inside CMS components</a>. Handler names should use the <code>onSomething</code> pattern, for example, <code>onName</code>. All handlers support the use of <a href="./update-partials.html">updating partials</a> as part of the AJAX request.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>If two handlers with the same name are defined in a page and layout together, the page handler will take priority. The handlers defined in components have the lowest priority.</p></div><h3 id="calling-a-handler"><a href="#calling-a-handler" class="header-anchor">#</a> Calling a Handler</h3><p>Every AJAX request should specify a handler name, either using the <a href="./../ajax/attributes-api.html">data attributes API</a> or the <a href="./../ajax/javascript-api.html">JavaScript API</a>. When the request is made, the server will search all the registered handlers and locate the first one it finds.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- Attributes API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- JavaScript API --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> oc<span class="token punctuation">.</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Handlers defined by pages, layouts and components are all registered automatically. If you are calling a handler from inside a partial, use the <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> Twig tag</a>, which adjusts the page cycle to register its handlers.</p><h3 id="form-serialization"><a href="#form-serialization" class="header-anchor">#</a> Form Serialization</h3><p>When an AJAX request occurs inside a HTML form tag, all the input values of the form are available to the handler. In the example below, the <code>first_name</code> value will be sent with the request.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>first_name<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The JavaScript API support this logic with the <code>oc.request</code> function.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;#myForm&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;onSubmitContactForm&#39;</span><span class="token punctuation">)</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>You may use the <code>input()</code> PHP function to access the variable.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSubmitContactForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$firstName</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="generic-handler"><a href="#generic-handler" class="header-anchor">#</a> Generic Handler</h3><p>Sometimes you may need to make an AJAX request for the sole purpose of updating page contents, not needing to execute any code. You may use the <code>onAjax</code> handler for this purpose. This handler is available everywhere without needing to write any code.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Do nothing<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="component-handlers"><a href="#component-handlers" class="header-anchor">#</a> Component Handlers</h3><p>If two components register the same handler name, it is advised to prefix the handler with the <a href="./../../cms/themes/components.html">component short name or alias</a>. If a component uses an alias of <strong>mycomponent</strong> the handler can be targeted with <code>mycomponent::onName</code>.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>mycomponent::onSubmitContactForm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Go<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>See the <a href="./../../extend/cms-components.html">Component Development article</a> to learn more.</p><h2 id="redirects-in-ajax-handlers"><a href="#redirects-in-ajax-handlers" class="header-anchor">#</a> Redirects in AJAX Handlers</h2><p>If you need to redirect the browser to another location, return the <code>Redirect</code> response object from the AJAX handler. The framework will redirect the browser as soon as the response is returned from the server. Example AJAX handler with a redirect.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onRedirectMe</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Redirect</span><span class="token operator">::</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;http://google.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="returning-data-from-ajax-handlers"><a href="#returning-data-from-ajax-handlers" class="header-anchor">#</a> Returning Data from AJAX Handlers</h2><p>The response from an AJAX handler can serve as consumable API by returning structured data. If an AJAX handler returns an array, you can access its elements in the <code>success</code> event handler. Example AJAX handler that returns a data object.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onFetchDataFromServer</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Some server-side code</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;totalUsers&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">1000</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;totalProjects&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">937</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The data can be fetched with the data attributes API.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The same with the JavaScript API.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript">oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">success</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span></span><span class="token punctuation">&quot;</span></span></span>
<span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="running-code-before-handlers"><a href="#running-code-before-handlers" class="header-anchor">#</a> Running Code Before Handlers</h2><p>Sometimes you may want code to execute before a handler executes. Defining an <code>onInit</code> function as part of the <a href="./../../cms/themes/layouts.html">Layout Execution Life Cycle</a> allows code to run before every AJAX handler.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onInit</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a page or layout PHP code section</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You may define an <code>init</code> method inside a <a href="./../../extend/cms-components.html">CMS component class</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// From a component or widget class</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="throwing-an-ajax-exception"><a href="#throwing-an-ajax-exception" class="header-anchor">#</a> Throwing an AJAX Exception</h2><p>You may throw an <a href="./../../extend/system/exceptions.html">AJAX exception</a> using the <code>AjaxException</code> class to treat the response as an error while retaining the ability to send response contents as normal. Simply pass the response contents as the first argument of the exception.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;error&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Not enough questions&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;questionsNeeded&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">2</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>These errors are handled by the AJAX framework.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onHandleForm<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-error</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>console.log(data)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The same with the JavaScript API.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token special-attr"><span class="token attr-name">onsubmit</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value javascript language-javascript">oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">,</span> <span class="token string">&#39;onHandleForm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">error</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token boolean">false</span></span><span class="token punctuation">&quot;</span></span></span>
<span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>When throwing this exception type <a href="./update-partials.html">partials will be updated</a> as normal.</p></div><h2 id="dispatching-browser-events"><a href="#dispatching-browser-events" class="header-anchor">#</a> Dispatching Browser Events</h2><div class="custom-block aside"><p>Dispatched events are triggered in an AJAX response after the request completes and before partials are updated.</p></div><p>You may dispatch JavaScript events from AJAX handlers using the <code>dispatchBrowserEvent</code> method. This method takes any event name (first argument) and detail variables to pass to the event (second argument), the variables must be compatible with JSON serialization.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onPerformAction</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:update-profile&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:update-profile&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Jeff&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In the browser, use the <code>addEventListener</code> to listen for the dispatched event when the AJAX request completes. The event variables are available via the <code>event.detail</code> object.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:update-profile&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;Profile updated with name: &#39;</span> <span class="token operator">+</span> event<span class="token punctuation">.</span>detail<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For example, if you want to show an alert that a document has already been updated by another user, you could dispatch an event to the browser and throw an <code>AjaxException</code> to halt the process.</p><div class="custom-block tip"><p><code>AjaxException</code> and <code>ValidationException</code> are halting exceptions that support dispatched events.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">dispatchBrowserEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app:stale-document&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div></div><p>You can listen to this event in the browser using a generic listener. This example prompts the user before resubmitting the request with a <code>force</code> flag set in the data.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:stale-document&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">confirm</span><span class="token punctuation">(</span><span class="token string">&#39;Another user has updated this document, proceed?&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        oc<span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span>event<span class="token punctuation">.</span>target<span class="token punctuation">,</span> <span class="token string">&#39;onUpdate&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span>
            <span class="token literal-property property">force</span><span class="token operator">:</span> <span class="token boolean">true</span>
        <span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To prevent the partials from updating as part of the response, call <code>preventDefault()</code> on the event object.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;app:stale-document&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span><span class="token function">preventDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,58))])}const w=p(u,[["render",r]]);export{v as __pageData,w as default};
